1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
41	
42	export interface ScenarioResult {
43	  results: StepResult[];
44	}
45	
46	const PROCESSING_FEE = 5;
47	
48	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
49	  sword: 100,
50	  amulet: 60,
51	  staff: 80,
52	  potion: 40,
53	  rune: 25,
54	  moonstone: 25,
55	};
56	
57	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
58	  sword: 1000,
59	  amulet: 600,
60	  staff: 800,
61	  potion: 400,
62	  rune: 250,
63	  moonstone: 250,
64	};
65	
66	const DEDUCTIBLE_PER_DAMAGE = 100;
67	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
68	const HALF_REIMBURSEMENT_RATE = 0.5;
69	const FULL_REIMBURSEMENT_RATE = 1;
70	const CAP_MULTIPLE = 2;
71	const ALIKE_ITEMS_PER_BLOCK = 3;
72	const BLOCK_BASE_PREMIUM = 60;
73	const CURSE_SURCHARGE_RATE = 0.5;
74	const SURCHARGE_ENCHANTMENT_LEVEL = 5;
75	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
76	const LOYALTY_YEARS_THRESHOLD = 2;
77	const LOYALTY_DISCOUNT_RATE = 0.2;
78	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
79	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
80	
81	const raise = (message: string): never => {
82	  throw new Error(message);
83	};
84	
85	const sum = (amounts: number[]): number =>
86	  amounts.reduce((total, amount) => total + amount, 0);
87	
88	const groupByType = (items: Item[]): Item[][] => {
89	  const itemsByType = new Map<string, Item[]>();
90	
91	  for (const item of items) {
92	    const alikeItems = itemsByType.get(item.type);
93	    if (alikeItems) alikeItems.push(item);
94	    else itemsByType.set(item.type, [item]);
95	  }
96	
97	  return [...itemsByType.values()];
98	};
99	
100	// Both catalogues are keyed by item type and must reject an unknown type the
101	// same way — a silent miss would turn into NaN further downstream.
102	const lookupByItemType = (catalogue: Record<string, number>, item: Item): number =>
103	  catalogue[item.type] ?? raise(`unknown item type: ${item.type}`);
104	
105	const basePremiumOf = (item: Item): number =>
106	  lookupByItemType(BASE_PREMIUM_BY_ITEM_TYPE, item);
107	
108	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
109	  alikeItems.length === ALIKE_ITEMS_PER_BLOCK
110	    ? BLOCK_BASE_PREMIUM
111	    : sum(alikeItems.map(basePremiumOf));
112	
113	const curseSurchargeOf = (item: Item): number =>
114	  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE_RATE : 0;
115	
116	const highEnchantmentSurchargeOf = (item: Item): number =>
117	  (item.enchantment ?? 0) >= SURCHARGE_ENCHANTMENT_LEVEL
118	    ? basePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
119	    : 0;
120	
121	const itemSurchargesOf = (item: Item): number =>
122	  curseSurchargeOf(item) + highEnchantmentSurchargeOf(item);
123	
124	// Policy-wide adjustments are rates on the base premium: surcharges are
125	// positive, discounts negative. Each applies only when its condition holds.
126	const policyAdjustmentRatesOf = (customer: Customer, isFollowUpQuote: boolean): number[] => [
127	  FIRST_INSURANCE_SURCHARGE_RATE,
128	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? -LOYALTY_DISCOUNT_RATE : 0,
129	  isFollowUpQuote ? -FOLLOW_UP_DISCOUNT_RATE : 0,
130	];
131	
132	const quote = (
133	  { items }: QuoteStep,
134	  customer: Customer,
135	  isFollowUpQuote: boolean,
136	): StepResult => {
137	  const basePremium = sum(groupByType(items).map(basePremiumOfAlikeItems));
138	  const itemSurcharges = sum(items.map(itemSurchargesOf));
139	  const policyAdjustments =
140	    basePremium * sum(policyAdjustmentRatesOf(customer, isFollowUpQuote));
141	
142	  return {
143	    premium: Math.ceil(basePremium + itemSurcharges + policyAdjustments + PROCESSING_FEE),
144	  };
145	};
146	
147	const insuranceValueOf = (item: Item): number =>
148	  lookupByItemType(INSURANCE_VALUE_BY_ITEM_TYPE, item);
149	
150	const insuranceSumOf = (items: Item[]): number => sum(items.map(insuranceValueOf));
151	
152	const reimbursementRateOf = (item: Item): number =>
153	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
154	    ? HALF_REIMBURSEMENT_RATE
155	    : FULL_REIMBURSEMENT_RATE;
156	
157	// Checked up front, before any item is consumed, so a later negative amount
158	// cannot leave a partially-processed incident behind.
159	const rejectNegativeAmounts = (damages: Damage[]): void => {
160	  const negative = damages.find((damage) => damage.amount < 0);
161	
162	  if (negative) raise(`negative damage amount: ${negative.amount}`);
163	};
164	
165	// Per-damage reimbursement, before the policy cap is applied in `claim`.
166	const reimbursementForDamage = (damage: Damage, damagedItem: Item): number =>
167	  damage.amount * reimbursementRateOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
168	
169	interface Policy {
170	  items: Item[];
171	  remainingCap: number;
172	}
173	
174	// A quote step opens a policy: it fixes the covered items and the cap, which
175	// is a multiple of the insurance sum and unaffected by premium modifiers.
176	const openPolicy = ({ items }: QuoteStep): Policy => ({
177	  items,
178	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE,
179	});
180	
181	// Each damage entry consumes one insured item, so a policy covering a single
182	// sword cannot absorb two sword damages.
183	const takeDamagedItem = (unclaimedItems: Item[], damage: Damage): Item => {
184	  const index = unclaimedItems.findIndex((item) => item.type === damage.itemType);
185	
186	  return index === -1
187	    ? raise(`item not covered by policy: ${damage.itemType}`)
188	    : unclaimedItems.splice(index, 1)[0];
189	};
190	
191	const claim = ({ incident }: ClaimStep, policy: Policy): StepResult => {
192	  rejectNegativeAmounts(incident.damages);
193	
194	  const unclaimedItems = [...policy.items];
195	  const desiredPayout = sum(
196	    incident.damages.map((damage) =>
197	      reimbursementForDamage(damage, takeDamagedItem(unclaimedItems, damage)),
198	    ),
199	  );
200	  const payout = Math.floor(Math.min(desiredPayout, policy.remainingCap));
201	  policy.remainingCap -= payout;
202	
203	  return { payout, remainingCap: policy.remainingCap };
204	};
205	
206	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
207	  const policyByStep = new Map<number, Policy>();
208	  let quotesSoFar = 0;
209	
210	  const results = steps.map((step, stepIndex) => {
211	    if (step.op === "claim") {
212	      return claim(step, policyByStep.get(step.policy) as Policy);
213	    }
214	
215	    policyByStep.set(stepIndex, openPolicy(step));
216	    const result = quote(step, customer, quotesSoFar > 0);
217	    quotesSoFar += 1;
218	
219	    return result;
220	  });
221	
222	  return { results };
223	};
